const express = require('express');
const crypto = require('crypto');
const { promisify } = require('util');

const app = express();
app.use(express.json());

// In-memory stores
const users = new Map();
const sessions = new Map();
const pendingMFA = new Map();

const TOTP_WINDOW = 1;
const TOTP_STEP = 30;
const TOKEN_BYTES = 32;

// HMAC-based TOTP implementation
function generateHOTP(secret, counter) {
  const buf = Buffer.alloc(8);
  // Write counter as big-endian 64-bit
  buf.writeUInt32BE(Math.floor(counter / 0x100000000), 0);
  buf.writeUInt32BE(counter & 0xFFFFFFFF, 4);

  const hmac = crypto.createHmac('sha1', Buffer.from(secret, 'base32hex'));
  hmac.update(buf);
  const digest = hmac.digest();

  const offset = digest[digest.length - 1] & 0x0F;
  const code = (digest.readUInt32BE(offset) & 0x7FFFFFFF) % 1000000;
  return code.toString().padStart(6, '0');
}

function getCurrentCounter() {
  return Math.floor(Date.now() / 1000 / TOTP_STEP);
}

function verifyTOTP(secret, inputCode, window) {
  const currentCounter = getCurrentCounter();
  // Check codes within the time window
  for (let i = -window; i <= window; i++) {
    const counter = currentCounter + i;
    // Ensure counter is valid (non-negative)
    if (counter < 0) continue;
    const expectedCode = generateHOTP(secret, counter);
    if (safeCompare(inputCode, expectedCode)) {
      return true;
    }
  }
  return false;
}

// Constant-time string comparison
function safeCompare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

// Password hashing with scrypt
const scryptAsync = promisify(crypto.scrypt);

async function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  const derived = await scryptAsync(password, salt, 64);
  return `${salt}:${derived.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, hash] = stored.split(':');
  const derived = await scryptAsync(password, salt, 64);
  const hashBuf = Buffer.from(hash, 'hex');
  return crypto.timingSafeEqual(derived, hashBuf);
}

// Generate secure session token
function generateToken() {
  return crypto.randomBytes(TOKEN_BYTES).toString('hex');
}

// Rate limiting
const loginAttempts = new Map();
const MAX_ATTEMPTS = 5;
const LOCKOUT_MS = 15 * 60 * 1000;

function checkRateLimit(identifier) {
  const record = loginAttempts.get(identifier);
  if (!record) return { allowed: true };
  if (Date.now() > record.lockedUntil) {
    loginAttempts.delete(identifier);
    return { allowed: true };
  }
  if (record.attempts >= MAX_ATTEMPTS) {
    return { allowed: false, retryAfter: record.lockedUntil - Date.now() };
  }
  return { allowed: true };
}

function recordAttempt(identifier) {
  const record = loginAttempts.get(identifier) || { attempts: 0, lockedUntil: 0 };
  record.attempts += 1;
  if (record.attempts >= MAX_ATTEMPTS) {
    record.lockedUntil = Date.now() + LOCKOUT_MS;
  }
  loginAttempts.set(identifier, record);
}

function resetAttempts(identifier) {
  loginAttempts.delete(identifier);
}

// Registration endpoint
app.post('/api/register', async (req, res) => {
  try {
    const { username, password } = req.body;
    if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid input' });
    }
    if (username.length < 3 || username.length > 30 || password.length < 8) {
      return res.status(400).json({ error: 'Validation failed' });
    }
    const normalizedUser = username.toLowerCase().trim();
    if (users.has(normalizedUser)) {
      return res.status(409).json({ error: 'User exists' });
    }

    const hashedPassword = await hashPassword(password);
    // Generate TOTP secret for MFA
    const totpSecret = crypto.randomBytes(20).toString('base32hex');

    users.set(normalizedUser, {
      passwordHash: hashedPassword,
      totpSecret: totpSecret,
      createdAt: Date.now()
    });

    res.status(201).json({ 
      message: 'User registered',
      totpSecret: totpSecret,
      note: 'Save this secret in your authenticator app'
    });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Login endpoint - step 1: password
app.post('/api/login', async (req, res) => {
  try {
    const { username, password } = req.body;
    if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid input' });
    }
    const normalizedUser = username.toLowerCase().trim();

    const rateCheck = checkRateLimit(normalizedUser);
    if (!rateCheck.allowed) {
      return res.status(429).json({ error: 'Too many attempts', retryAfter: rateCheck.retryAfter });
    }

    const user = users.get(normalizedUser);
    if (!user) {
      // Dummy hash to prevent timing enumeration
      await scryptAsync(password, 'dummysalt1234567', 64);
      recordAttempt(normalizedUser);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const passwordValid = await verifyPassword(password, user.passwordHash);
    if (!passwordValid) {
      recordAttempt(normalizedUser);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Password correct, require MFA
    const mfaToken = crypto.randomBytes(16).toString('hex');
    pendingMFA.set(mfaToken, {
      username: normalizedUser,
      expiresAt: Date.now() + 5 * 60 * 1000, // 5 min to complete MFA
      verified: false
    });

    res.status(200).json({ 
      message: 'Password accepted, MFA required',
      mfaToken: mfaToken
    });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Login endpoint - step 2: TOTP verification
app.post('/api/login/mfa', (req, res) => {
  try {
    const { mfaToken, totpCode } = req.body;
    if (!mfaToken || !totpCode || typeof mfaToken !== 'string' || typeof totpCode !== 'string') {
      return res.status(400).json({ error: 'Invalid input' });
    }

    const pending = pendingMFA.get(mfaToken);
    if (!pending || Date.now() > pending.expiresAt) {
      pendingMFA.delete(mfaToken);
      return res.status(401).json({ error: 'Invalid or expired MFA session' });
    }

    // Enforce rate limiting on the MFA step to prevent TOTP brute force
    const rateCheck = checkRateLimit(pending.username);
    if (!rateCheck.allowed) {
      return res.status(429).json({ error: 'Too many attempts', retryAfter: rateCheck.retryAfter });
    }

    const user = users.get(pending.username);
    if (!user) {
      pendingMFA.delete(mfaToken);
      return res.status(401).json({ error: 'User not found' });
    }

    // Verify TOTP code with fixed window
    const isValid = verifyTOTP(user.totpSecret, totpCode.trim(), TOTP_WINDOW);

    if (!isValid) {
      recordAttempt(pending.username);
      return res.status(401).json({ error: 'Invalid TOTP code' });
    }

    // MFA passed, create session
    pendingMFA.delete(mfaToken);
    resetAttempts(pending.username);

    const sessionToken = generateToken();
    sessions.set(sessionToken, {
      username: pending.username,
      createdAt: Date.now()
    });

    res.status(200).json({ token: sessionToken });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Protected endpoint
app.get('/api/profile', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  const token = authHeader.slice(7);
  const session = sessions.get(token);
  if (!session) {
    return res.status(401).json({ error: 'Invalid session' });
  }
  // Check session expiry (1 hour)
  if (Date.now() - session.createdAt > 3600000) {
    sessions.delete(token);
    return res.status(401).json({ error: 'Session expired' });
  }
  const user = users.get(session.username);
  res.json({ username: session.username, createdAt: user.createdAt });
});

app.listen(3000);
module.exports = app;
